static inline bool consume_bool(pni_consumer_t* consumer, bool *b) {
  *b = false;
  uint8_t type;
  if (!pni_consumer_readf8(consumer, &type)) return false;
  switch (type) {
    case PNE_BOOLEAN: {
      uint8_t ub;
      if (!pni_consumer_readf8(consumer, &ub)) return false;
      *b = ub;
      return true;
    }
    case PNE_FALSE:
      *b = false;
      return true;
    case PNE_TRUE:
      *b = true;
      return true;
    default:
      pni_consumer_skip_value(consumer, type);
      return false;
  }
}
